const useVisibilityPolling = (queryKey, queryFn, interval = 5000) => {
  const [isVisible, setIsVisible] = useState(true);

  useEffect(() => {
    const handleVisibilityChange = () => {
      setIsVisible(document.visibilityState === 'visible');
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  return useQuery({
    queryKey,
    queryFn,
    enabled: isVisible,
    refetchInterval: isVisible ? interval : false
  });
};

const LiveDashboard = () => {
  const [isLive, setIsLive] = useState(true);

  const { data: metrics } = useQuery({
    queryKey: ['metrics'],
    queryFn: fetchMetrics,
    refetchInterval: isLive ? 2000 : false,
    enabled: true
  });

  return (
    <div>
      <button onClick={() => setIsLive(!isLive)}>
        {isLive ? 'Pause Live Updates' : 'Resume Live Updates'}
      </button>
      <MetricsDisplay data={metrics} />
    </div>
  );
};

const useWebSocketTicker = (symbol: string) => {
  const queryClient = useQueryClient();

  useEffect(() => {
    const ws = new WebSocket(`wss://stream.example.com/${symbol}`);

    ws.onmessage = (event) => {
      const tick = JSON.parse(event.data);

      queryClient.setQueryData(['ticker', symbol], (old: TickerData) => ({
        ...old,
        price: tick.price,
        change: tick.change,
        lastUpdated: new Date().toISOString()
      }));
    };

    ws.onclose = () => {
      console.log('WebSocket disconnected');
    };

    return () => ws.close();
  }, [symbol, queryClient]);

  return useQuery({
    queryKey: ['ticker', symbol],
    queryFn: () => fetchTicker(symbol),
    staleTime: Infinity
  });
};

// General Programming Example
class Example {
  constructor(config) {
    this.config = {
      enabled: true,
      debug: false,
      maxRetries: 3,
      timeout: 5000,
      ...config
    };
  }

  async process(input) {
    // Step 1: Validate input
    this.validate(input);

    // Step 2: Process with retry logic
    let attempts = 0;
    while (attempts < this.config.maxRetries) {
      try {
        const result = await this.execute(input);
        return { success: true, data: result };
      } catch (error) {
        attempts++;
        if (attempts >= this.config.maxRetries) {
          return { success: false, error: error.message };
        }
      }
    }
  }

  validate(input) {
    if (!input) {
      throw new Error('Input cannot be null or undefined');
    }
  }

  async execute(input) {
    // Implementation here
    return { processed: true, timestamp: Date.now() };
  }
}

// Usage
const example = new Example({ debug: true });
example.process({ id: 1 }).then(console.log);

